export default JSON.parse("{\"workId\":\"xunzi\",\"chapter\":{\"id\":\"xunzi_ch-12\",\"workId\":\"xunzi\",\"order\":12,\"title\":\"君道\",\"difficulty\":4,\"estimatedMinutes\":16,\"passageIds\":[\"xunzi_ch-12_p-1\",\"xunzi_ch-12_p-2\",\"xunzi_ch-12_p-3\",\"xunzi_ch-12_p-4\",\"xunzi_ch-12_p-5\",\"xunzi_ch-12_p-6\",\"xunzi_ch-12_p-7\",\"xunzi_ch-12_p-8\",\"xunzi_ch-12_p-9\",\"xunzi_ch-12_p-10\",\"xunzi_ch-12_p-11\",\"xunzi_ch-12_p-12\"],\"tags\":[\"儒家\",\"性惡論\",\"禮樂\"]},\"passages\":[{\"id\":\"xunzi_ch-12_p-1\",\"chapterId\":\"xunzi_ch-12\",\"order\":1,\"canonicalText\":\"有亂君，無亂國；有治人，無治法，羿之法非亡也，而羿不世中；禹之法猶存，而夏不世王。故法不能獨立，類不能自行；得其人則存，失其人則亡。法者、治之端也；君子者、法之原也。故有君子，則法雖省，足以遍矣；無君子，則法雖具，失先後之施，不能應事之變，足以亂矣。不知法之義，而正法之數者，雖博臨事必亂。故明主急得其人，而闇主急得其埶。急得其人，則身佚而國治，功大而名美，上可以王，下可以霸；不急得其人，而急得其埶，則身勞而國亂，功廢而名辱，社稷必危。故君人者，勞於索之，而休於使之。《書》曰：「惟文王敬忌，一人以擇。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-12_p-1_s-1\",\"xunzi_ch-12_p-1_s-2\",\"xunzi_ch-12_p-1_s-3\",\"xunzi_ch-12_p-1_s-4\",\"xunzi_ch-12_p-1_s-5\",\"xunzi_ch-12_p-1_s-6\",\"xunzi_ch-12_p-1_s-7\",\"xunzi_ch-12_p-1_s-8\",\"xunzi_ch-12_p-1_s-9\",\"xunzi_ch-12_p-1_s-10\",\"xunzi_ch-12_p-1_s-11\",\"xunzi_ch-12_p-1_s-12\",\"xunzi_ch-12_p-1_s-13\",\"xunzi_ch-12_p-1_s-14\",\"xunzi_ch-12_p-1_s-15\",\"xunzi_ch-12_p-1_s-16\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 1 節）中論述道：有亂君，無亂國；有治人，無治國家典章法度，羿的國家典章法度絕不是亡啊，而且羿不世中；禹的國家典章法度猶存，而且夏不世王。所以國家典章法度不能獨立，類不能自行；得他的人則存，失他的人則亡。國家典章法度的人或事物、治的端啊；君子的人或事物、國家典章法度的原啊。所以有君子，則國家典章法度雖省，足以遍矣；無君子，則國家典章法度雖具，失先後的施，不能應事的變，足以亂矣。不知國家典章法度的正義道義，而且正國家典章法度的數的人或事物，雖博臨事必亂。所以明主急得他的人，而且闇主急得他的埶。急得他的人，則身佚而且國治，功大而且名美，上可以王，下可以霸；不急得他的人，而且急得他的埶，則身勞而且國亂，功廢而且名辱，社稷必危。所以君人的人或事物，勞於索的，而且休於使的。《書》說道：：惟文王敬忌，一人以擇。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 1 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「有亂君，無亂國」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「有亂君，無亂國；有治人，無治法，羿之法非亡也，而羿不……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-2\",\"chapterId\":\"xunzi_ch-12\",\"order\":2,\"canonicalText\":\"合符節，別契券者，所以為信也；上好權謀，則臣下百吏誕詐之人乘是而後欺。探籌、投鉤者，所以為公也；上好曲私，則臣下百吏乘是而後偏。衡石稱縣者，所以為平也；上好覆傾，則臣下百吏乘是而後險。鬥斛敦概者，所以為嘖也；上好貪利，則臣下百吏乘是而後豐取刻與，以無度取於民。故械數者，治之流也，非治之原也；君子者，治之原也。官人守數，君子養原；原清則流清，原濁則流濁。故上好禮義，尚賢使能，無貪利之心，則下亦將綦辭讓，致忠信，而謹於臣子矣。如是則雖在小民，不待合符節，別契券而信，不待探籌投鉤而公，不待衝石稱縣而平，不待鬥斛敦概而嘖。故賞不用而民勸，罰不用而民服，有司不勞而事治，政令不煩而俗美。百姓莫敢不順上之法，象上之志，而勸上之事，而安樂之矣。故藉歛忘費，事業忘勞，寇難忘死，城郭不待飾而固，兵刃不待陵而勁，敵國不待服而詘，四海之民不待令而一，夫是之謂至平。《詩》曰：「王猶允塞，徐方既來。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-12_p-2_s-1\",\"xunzi_ch-12_p-2_s-2\",\"xunzi_ch-12_p-2_s-3\",\"xunzi_ch-12_p-2_s-4\",\"xunzi_ch-12_p-2_s-5\",\"xunzi_ch-12_p-2_s-6\",\"xunzi_ch-12_p-2_s-7\",\"xunzi_ch-12_p-2_s-8\",\"xunzi_ch-12_p-2_s-9\",\"xunzi_ch-12_p-2_s-10\",\"xunzi_ch-12_p-2_s-11\",\"xunzi_ch-12_p-2_s-12\",\"xunzi_ch-12_p-2_s-13\",\"xunzi_ch-12_p-2_s-14\",\"xunzi_ch-12_p-2_s-15\",\"xunzi_ch-12_p-2_s-16\",\"xunzi_ch-12_p-2_s-17\",\"xunzi_ch-12_p-2_s-18\",\"xunzi_ch-12_p-2_s-19\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 2 節）中論述道：合符節，別契券的人或事物，所以為信啊；上好權謀，則臣下百吏誕詐的人乘是而且後欺。探籌、投鉤的人或事物，所以為公啊；上好曲私，則臣下百吏乘是而且後偏。衡石稱縣的人或事物，所以為平啊；上好覆傾，則臣下百吏乘是而且後險。鬥斛敦概的人或事物，所以為嘖啊；上好貪利，則臣下百吏乘是而且後豐取刻與，以無度取於民。所以械數的人或事物，治的流啊，絕不是治的原啊；君子的人或事物，治的原啊。官人守數，君子養原；原清則流清，原濁則流濁。所以上好禮正義道義道品德修養規程正義道義，尚賢使能，無貪利的心，則下亦將綦辭讓，致忠信，而且謹於臣子矣。如是則雖在小民，不待合符節，別契券而且信，不待探籌投鉤而且公，不待衝石稱縣而且平，不待鬥斛敦概而且嘖。所以賞不用而且民勸，罰不用而且民服，有司不勞而且事治，政令不煩而且俗美。百姓莫敢不順上的國家典章法度，象上的志，而且勸上的事，而且安樂的矣。所以藉歛忘費，事業忘勞，寇難忘死，城郭不待飾而且固，兵刃不待陵而且勁，敵國不待服而且詘，四海的民不待令而且一，這就是儒家所稱的至平。《詩》說道：：王猶允塞，徐方既來。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 2 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「合符節，別契券者，所以為信也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「合符節，別契券者，所以為信也；上好權謀，則臣下百吏誕……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-3\",\"chapterId\":\"xunzi_ch-12\",\"order\":3,\"canonicalText\":\"請問為人君？曰：以禮分施，均遍而不偏。請問為人臣？曰：以禮侍君，忠順而不懈。請問為人父？曰：寬惠而有禮。請問為人子？曰：敬愛而致文。請問為人兄？曰：慈愛而見友。請問為人弟？曰：敬詘而不苟。請問為人夫？曰：致功而不流，致臨而有辨。請問為人妻？曰：夫有禮則柔從聽侍，夫無禮則恐懼而自竦也。此道也，偏立而亂，俱立而治，其足以稽矣。請問兼能之奈何？曰：審之禮也。古者先王審禮以方皇周浹於天下，動無不當也。故君子恭而不難，敬而不鞏，貧窮而不約，富貴而不驕，並遇變態而不窮，審之禮也。故君子之於禮，敬而安之；其於事也，徑而不失；其於人也，寡怨寬裕而無阿；其為身也，謹修飾而不危；其應變故也，齊給便捷而不惑；其於天地萬物也，不務說其所以然，而致善用其材；其於百官之事伎藝之人也，不與之爭能，而致善用其功；其待上也，忠順而不懈；其使下也，均遍而不偏；其交遊也，緣類而有義；其居鄉里也，容而不亂。是故窮則必有名，達則必有功，仁厚兼覆天下而不閔，明達用天地理萬變而不疑，血氣和平，志意廣大，行義塞於天地之間，仁智之極也。夫是之謂聖人；審之禮也。\",\"sentenceIds\":[\"xunzi_ch-12_p-3_s-1\",\"xunzi_ch-12_p-3_s-2\",\"xunzi_ch-12_p-3_s-3\",\"xunzi_ch-12_p-3_s-4\",\"xunzi_ch-12_p-3_s-5\",\"xunzi_ch-12_p-3_s-6\",\"xunzi_ch-12_p-3_s-7\",\"xunzi_ch-12_p-3_s-8\",\"xunzi_ch-12_p-3_s-9\",\"xunzi_ch-12_p-3_s-10\",\"xunzi_ch-12_p-3_s-11\",\"xunzi_ch-12_p-3_s-12\",\"xunzi_ch-12_p-3_s-13\",\"xunzi_ch-12_p-3_s-14\",\"xunzi_ch-12_p-3_s-15\",\"xunzi_ch-12_p-3_s-16\",\"xunzi_ch-12_p-3_s-17\",\"xunzi_ch-12_p-3_s-18\",\"xunzi_ch-12_p-3_s-19\",\"xunzi_ch-12_p-3_s-20\",\"xunzi_ch-12_p-3_s-21\",\"xunzi_ch-12_p-3_s-22\",\"xunzi_ch-12_p-3_s-23\",\"xunzi_ch-12_p-3_s-24\",\"xunzi_ch-12_p-3_s-25\",\"xunzi_ch-12_p-3_s-26\",\"xunzi_ch-12_p-3_s-27\",\"xunzi_ch-12_p-3_s-28\",\"xunzi_ch-12_p-3_s-29\",\"xunzi_ch-12_p-3_s-30\",\"xunzi_ch-12_p-3_s-31\",\"xunzi_ch-12_p-3_s-32\",\"xunzi_ch-12_p-3_s-33\",\"xunzi_ch-12_p-3_s-34\",\"xunzi_ch-12_p-3_s-35\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 3 節）中論述道：請問為人君？說道：：以禮正義道義道品德修養規程分施，均遍而且不偏。請問為人臣？說道：：以禮正義道義道品德修養規程侍君，忠順而且不懈。請問為人父？說道：：寬惠而且有禮正義道義道品德修養規程。請問為人子？說道：：敬愛而且致文。請問為人兄？說道：：慈愛而且見友。請問為人弟？說道：：敬詘而且不苟。請問為人夫？說道：：致功而且不流，致臨而且有辨。請問為人妻？說道：：夫有禮正義道義道品德修養規程則柔從聽侍，夫無禮正義道義道品德修養規程則恐懼而且自竦啊。此道啊，偏立而且亂，俱立而且治，他的足以稽矣。請問兼能的奈何？說道：：審的禮正義道義道品德修養規程啊。古的人或事物先王審禮正義道義道品德修養規程以方皇周浹於天下，動無不當啊。所以君子恭而且不難，敬而且不鞏，貧窮而且不約，富貴而且不驕，並遇變態而且不窮，審的禮正義道義道品德修養規程啊。所以君子的於禮正義道義道品德修養規程，敬而且安的；他的於事啊，徑而且不失；他的於人啊，寡怨寬裕而且無阿；他的為身啊，謹修飾而且不危；他的應變所以啊，齊給便捷而且不惑；他的於天地萬物啊，不務說他的所以然，而且致善用他的材；他的於百官的事伎藝的人啊，不與的爭能，而且致善用他的功；他的待上啊，忠順而且不懈；他的使下啊，均遍而且不偏；他的交遊啊，緣類而且有正義道義；他的居鄉里啊，容而且不亂。正因為如此窮則必有名，達則必有功，仁愛慈悲之德厚兼覆天下而且不閔，明達用天地理萬變而且不疑，血氣和平，志意廣大，行正義道義塞於天地的間，仁愛慈悲之德智的極啊。這就是儒家所稱的聖人；審的禮正義道義道品德修養規程啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 3 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「請問為人君」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「請問為人君？曰：以禮分施，均遍而不偏。請問為人臣？曰……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-4\",\"chapterId\":\"xunzi_ch-12\",\"order\":4,\"canonicalText\":\"請問為國？曰聞修身，未嘗聞為國也。君者儀也，民者景也，儀正而景正。君者槃也，民者水也，槃圓而水圓。君者盂也，盂方而水方。君射則臣決。楚莊王好細腰，故朝有餓人。故曰：聞修身，未嘗聞為國也。\",\"sentenceIds\":[\"xunzi_ch-12_p-4_s-1\",\"xunzi_ch-12_p-4_s-2\",\"xunzi_ch-12_p-4_s-3\",\"xunzi_ch-12_p-4_s-4\",\"xunzi_ch-12_p-4_s-5\",\"xunzi_ch-12_p-4_s-6\",\"xunzi_ch-12_p-4_s-7\",\"xunzi_ch-12_p-4_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 4 節）中論述道：請問為國？說道：聞修身，未嘗聞為國啊。君的人或事物儀啊，民的人或事物景啊，儀正而且景正。君的人或事物槃啊，民的人或事物水啊，槃圓而且水圓。君的人或事物盂啊，盂方而且水方。君射則臣決。楚莊王好細腰，所以朝有餓人。所以古聖先賢說道：：聞修身，未嘗聞為國啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 4 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「請問為國」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「請問為國？曰聞修身，未嘗聞為國也。君者儀也，民者景也……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-5\",\"chapterId\":\"xunzi_ch-12\",\"order\":5,\"canonicalText\":\"君者，民之原也；原清則流清，原濁則流濁。故有社稷者而不能愛民，不能利民，而求民之親愛己，不可得也。民不親不愛，而求為己用，為己死，不可得也。民不為己用，不為己死，而求兵之勁，城之固，不可得也。兵不勁，城不固，而求敵之不至，不可得也。敵至而求無危削，不滅亡，不可得也。危削滅亡之情，舉積此矣，而求安樂，是狂生者也。狂生者，不胥時而落。故人主欲彊固安樂，則莫若反之民；欲附下一民，則莫若反之政；欲脩政美俗，則莫若求其人。彼或蓄積而得之者不世絕。彼其人者，生乎今之世，而志乎古之道。以天下之王公莫好之也，然而是子獨好之；以天下之民莫為1之也，然而是子獨為之。好之者貧，為之者窮，然而是子猶將為之也，不為少頃輟焉。曉然獨明於先王之所以得之，所以失之，知國之安危臧否，若別白黑。是其人也，大用之，則天下為一，諸侯為臣；小用之，則威行鄰敵；縱不能用，使無去其疆域，則國終身無故。故君人者，愛民而安，好士而榮，兩者無一焉而亡。《詩》曰：「介人維藩，大師為垣。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-12_p-5_s-1\",\"xunzi_ch-12_p-5_s-2\",\"xunzi_ch-12_p-5_s-3\",\"xunzi_ch-12_p-5_s-4\",\"xunzi_ch-12_p-5_s-5\",\"xunzi_ch-12_p-5_s-6\",\"xunzi_ch-12_p-5_s-7\",\"xunzi_ch-12_p-5_s-8\",\"xunzi_ch-12_p-5_s-9\",\"xunzi_ch-12_p-5_s-10\",\"xunzi_ch-12_p-5_s-11\",\"xunzi_ch-12_p-5_s-12\",\"xunzi_ch-12_p-5_s-13\",\"xunzi_ch-12_p-5_s-14\",\"xunzi_ch-12_p-5_s-15\",\"xunzi_ch-12_p-5_s-16\",\"xunzi_ch-12_p-5_s-17\",\"xunzi_ch-12_p-5_s-18\",\"xunzi_ch-12_p-5_s-19\",\"xunzi_ch-12_p-5_s-20\",\"xunzi_ch-12_p-5_s-21\",\"xunzi_ch-12_p-5_s-22\",\"xunzi_ch-12_p-5_s-23\",\"xunzi_ch-12_p-5_s-24\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 5 節）中論述道：君的人或事物，民的原啊；原清則流清，原濁則流濁。所以有社稷的人或事物而且不能愛民，不能利民，而且求民的親愛己，不可得啊。民不親不愛，而且求為己用，為己死，不可得啊。民不為己用，不為己死，而且求兵的勁，城的固，不可得啊。兵不勁，城不固，而且求敵的不至，不可得啊。敵至而且求無危削，不滅亡，不可得啊。危削滅亡的情，舉積此矣，而且求安樂，是狂生的人或事物啊。狂生的人或事物，不胥時而且落。所以人主欲彊固安樂，則莫若反的民；欲附下一民，則莫若反的政；欲脩政美俗，則莫若求他的人。彼或蓄積而且得的的人或事物不世絕。彼他的人的人或事物，生乎今的世，而且志乎古的道。以天下的王公莫好的啊，然而且是子獨好的；以天下的民莫為1的啊，然而且是子獨為的。好的的人或事物貧，為的的人或事物窮，然而且是子猶將為的啊，不為少頃輟焉。曉然獨明於先王的所以得的，所以失的，知國的安危臧否，若別白黑。是他的人啊，大用的，則天下為一，諸侯為臣；小用的，則威行鄰敵；縱不能用，使無去他的疆域，則國終身無所以。所以君人的人或事物，愛民而且安，好士而且榮，兩的人或事物無一焉而且亡。《詩》說道：：介人維藩，大師為垣。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 5 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「君者，民之原也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「君者，民之原也；原清則流清，原濁則流濁。故有社稷者而……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-6\",\"chapterId\":\"xunzi_ch-12\",\"order\":6,\"canonicalText\":\"道者，何也？曰：君之所1道也。君者，何也？曰：能羣也。能羣也者，何也？曰：善生養人者也，善班治人者也，善顯設人者也，善藩飾人者也。善生養人者人親之，善班治人者人安之，善顯設人者人樂之，善藩飾人者人榮之。四統者俱，而天下歸之，夫是之謂能羣。不能生養人者，人不親也；不能班治人者，人不安也；不能顯設人者，人不樂也；不能藩飾人者，人不榮也。四統者亡，而天下去之，夫是之謂匹夫。故曰：道存則國存，道亡則國亡。省工賈，眾農夫，禁盜賊，除姦邪：是所以生養之也。天子三公，諸侯一相，大夫擅官，士保職，莫不法度而公：是所以班治之也。論德而定次，量能而授官，皆使人載其事，而各得其所宜，上賢使之為三公，次賢使之為諸侯，下賢使之為士大夫：是所以顯設之也。修冠弁衣裳，黼黻文章，琱琢刻鏤，皆有等差：是所以藩飾之也。故由天子至於庶人也，莫不騁其能，得其志，安樂其事，是所同也；衣煖而食充，居安而遊樂，事時制明而用足，是又所同也。若夫重色而成文章，重味而成珍備，是所衍也。聖王財衍，以明辨異，上以飾賢良而明貴賤，下以飾長幼而明親疏。上在王公之朝，下在百姓之家，天下曉然皆知其所非以為異也，將以明分達治而保萬世也。故天子諸侯無靡費之用，士大夫無流淫之行，百吏官人無怠慢之事，眾庶百姓無姦怪之俗，無盜賊之罪，其能以稱義徧矣。故曰：治則衍及百姓，亂則不足及王公。此之謂也。\",\"sentenceIds\":[\"xunzi_ch-12_p-6_s-1\",\"xunzi_ch-12_p-6_s-2\",\"xunzi_ch-12_p-6_s-3\",\"xunzi_ch-12_p-6_s-4\",\"xunzi_ch-12_p-6_s-5\",\"xunzi_ch-12_p-6_s-6\",\"xunzi_ch-12_p-6_s-7\",\"xunzi_ch-12_p-6_s-8\",\"xunzi_ch-12_p-6_s-9\",\"xunzi_ch-12_p-6_s-10\",\"xunzi_ch-12_p-6_s-11\",\"xunzi_ch-12_p-6_s-12\",\"xunzi_ch-12_p-6_s-13\",\"xunzi_ch-12_p-6_s-14\",\"xunzi_ch-12_p-6_s-15\",\"xunzi_ch-12_p-6_s-16\",\"xunzi_ch-12_p-6_s-17\",\"xunzi_ch-12_p-6_s-18\",\"xunzi_ch-12_p-6_s-19\",\"xunzi_ch-12_p-6_s-20\",\"xunzi_ch-12_p-6_s-21\",\"xunzi_ch-12_p-6_s-22\",\"xunzi_ch-12_p-6_s-23\",\"xunzi_ch-12_p-6_s-24\",\"xunzi_ch-12_p-6_s-25\",\"xunzi_ch-12_p-6_s-26\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 6 節）中論述道：道的人或事物，何啊？說道：：君的所1道啊。君的人或事物，何啊？說道：：能羣啊。能羣啊的人或事物，何啊？說道：：善生養人的人或事物啊，善班治人的人或事物啊，善顯設人的人或事物啊，善藩飾人的人或事物啊。善生養人的人或事物人親的，善班治人的人或事物人安的，善顯設人的人或事物人樂的，善藩飾人的人或事物人榮的。四統的人或事物俱，而且天下歸的，這就是儒家所稱的能羣。不能生養人的人或事物，人不親啊；不能班治人的人或事物，人不安啊；不能顯設人的人或事物，人不樂啊；不能藩飾人的人或事物，人不榮啊。四統的人或事物亡，而且天下去的，這就是儒家所稱的匹夫。所以古聖先賢說道：：道存則國存，道亡則國亡。省工賈，眾農夫，禁盜賊，除姦邪：是所以生養的啊。天子三公，諸侯一相，大夫擅官，士保職，莫不國家典章法度度而且公：是所以班治的啊。論品德修養而且定次，量能而且授官，皆使人載他的事，而且各得他的所宜，上賢使的為三公，次賢使的為諸侯，下賢使的為士大夫：是所以顯設的啊。修冠弁衣裳，黼黻文章，琱琢刻鏤，皆有等差：是所以藩飾的啊。所以由天子至於庶人啊，莫不騁他的能，得他的志，安樂他的事，是所同啊；衣煖而且食充，居安而且遊樂，事時制明而且用足，是又所同啊。至於談到那重色而且成文章，重味而且成珍備，是所衍啊。聖王財衍，以明辨異，上以飾賢良而且明貴賤，下以飾長幼而且明親疏。上在王公的朝，下在百姓的家，天下曉然皆知他的所絕不是以為異啊，將以明分達治而且保萬世啊。所以天子諸侯無靡費的用，士大夫無流淫的行，百吏官人無怠慢的事，眾庶百姓無姦怪的俗，無盜賊的罪，他的能以稱正義道義徧矣。所以古聖先賢說道：：治則衍及百姓，亂則不足及王公。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 6 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「道者，何也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「道者，何也？曰：君之所1道也。君者，何也？曰：能羣也……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-7\",\"chapterId\":\"xunzi_ch-12\",\"order\":7,\"canonicalText\":\"至道大形：隆禮至法則國有常，尚賢使能則民知方，纂論公察則民不疑，賞克罰偷則民不怠，兼聽齊明則天下歸之；然後明分職，序事業，材技官能，莫不治理，則公道達而私門塞矣，公義明而私事息矣：如是，則德厚者進而佞說者止，貪利者退而廉節者起。《書》曰：「先時者殺無赦，不逮時者殺無赦。」人習其事而固，人之百事，如耳目鼻口之不可以相借官也。故職分而民不慢1，次定而序不亂，兼聽齊明而百姓不留：如是，則臣下百吏至於庶人，莫不修己而後敢安止，誠能而後敢受職；百姓易俗，小人變心，姦怪之屬莫不反愨：夫是之謂政教之極。故天子不視而見，不聽而聰，不慮而知，不動而功，塊然獨坐而天下從之如一體，如四胑之從心：夫是之謂大形。《詩》曰：「溫溫恭人，維德之基。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-12_p-7_s-1\",\"xunzi_ch-12_p-7_s-2\",\"xunzi_ch-12_p-7_s-3\",\"xunzi_ch-12_p-7_s-4\",\"xunzi_ch-12_p-7_s-5\",\"xunzi_ch-12_p-7_s-6\",\"xunzi_ch-12_p-7_s-7\",\"xunzi_ch-12_p-7_s-8\",\"xunzi_ch-12_p-7_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 7 節）中論述道：至道大形：隆禮正義道義道品德修養規程至國家典章法度則國有常，尚賢使能則民知方，纂論公察則民不疑，賞克罰偷則民不怠，兼聽齊明則天下歸的；然後明分職，序事業，材技官能，莫不治理，則公道達而且私門塞矣，公正義道義明而且私事息矣：如是，則品德修養厚的人或事物進而且佞說的人或事物止，貪利的人或事物退而且廉節的人或事物起。《書》說道：：先時的人或事物殺無赦，不逮時的人或事物殺無赦。人習他的事而且固，人的百事，如耳目鼻口的不可以相借官啊。所以職分而且民不慢1，次定而且序不亂，兼聽齊明而且百姓不留：如是，則臣下百吏至於庶人，莫不修己而且後敢安止，誠能而且後敢受職；百姓易俗，小人變心，姦怪的屬莫不反愨：這就是儒家所稱的政教的極。所以天子不視而且見，不聽而且聰，不慮而且知，不動而且功，塊然獨坐而且天下從的如一體，如四胑的從心：這就是儒家所稱的大形。《詩》說道：：溫溫恭人，維品德修養的基。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 7 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「至道大形：隆禮至法則國有常，尚賢使能則民知方，纂論公察則民不疑，賞克罰偷則民不怠，兼聽齊明則天下歸之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「至道大形：隆禮至法則國有常，尚賢使能則民知方，纂論公……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-8\",\"chapterId\":\"xunzi_ch-12\",\"order\":8,\"canonicalText\":\"為人主者，莫不欲彊而惡弱，欲安而惡危，欲榮而惡辱，是禹桀之所同也。要此三欲，闢此三惡，果何道而便？曰：在慎取相，道莫徑是矣。故知而不仁，不可；仁而不知，不可；既知且仁，是人主之寶也，王霸之佐也。不急得，不知；得而不用，不仁。無其人而幸有其功，愚莫大焉。今人主有大患：使賢者為之，則與不肖者規之；使知者慮之，則與愚者論之；使脩士行之，則與汙邪之人疑之，雖欲成功，得乎哉！譬之，是猶立直木而恐其景之枉也，惑莫大焉！語曰：好女之色，惡者之孽也；公正之士，眾人之痤也；脩道之人，汙邪之賊也。今使汙邪之人，論其怨賊，而求其無偏，得乎哉！譬之，是猶立枉木而求其景之直也，亂莫大焉。\",\"sentenceIds\":[\"xunzi_ch-12_p-8_s-1\",\"xunzi_ch-12_p-8_s-2\",\"xunzi_ch-12_p-8_s-3\",\"xunzi_ch-12_p-8_s-4\",\"xunzi_ch-12_p-8_s-5\",\"xunzi_ch-12_p-8_s-6\",\"xunzi_ch-12_p-8_s-7\",\"xunzi_ch-12_p-8_s-8\",\"xunzi_ch-12_p-8_s-9\",\"xunzi_ch-12_p-8_s-10\",\"xunzi_ch-12_p-8_s-11\",\"xunzi_ch-12_p-8_s-12\",\"xunzi_ch-12_p-8_s-13\",\"xunzi_ch-12_p-8_s-14\",\"xunzi_ch-12_p-8_s-15\",\"xunzi_ch-12_p-8_s-16\",\"xunzi_ch-12_p-8_s-17\",\"xunzi_ch-12_p-8_s-18\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 8 節）中論述道：為人主的人或事物，莫不欲彊而且惡弱，欲安而且惡危，欲榮而且惡辱，是禹桀的所同啊。要此三欲，闢此三惡，果何道而且便？說道：：在慎取相，道莫徑是矣。所以知而且不仁愛慈悲之德，不可；仁愛慈悲之德而且不知，不可；既知且仁愛慈悲之德，是人主的寶啊，王霸的佐啊。不急得，不知；得而且不用，不仁愛慈悲之德。無他的人而且幸有他的功，愚莫大焉。今人主有大患：使賢的人或事物為的，則與不肖的人或事物規的；使知的人或事物慮的，則與愚的人或事物論的；使脩士行的，則與汙邪的人疑的，雖欲成功，得乎哉！譬的，是猶立直木而且恐他的景的枉啊，惑莫大焉！語說道：：好女的色，惡的人或事物的孽啊；公正的士，眾人的痤啊；脩道的人，汙邪的賊啊。今使汙邪的人，論他的怨賊，而且求他的無偏，得乎哉！譬的，是猶立枉木而且求他的景的直啊，亂莫大焉。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 8 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「為人主者，莫不欲彊而惡弱，欲安而惡危，欲榮而惡辱，是禹桀之所同也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「為人主者，莫不欲彊而惡弱，欲安而惡危，欲榮而惡辱，是……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-9\",\"chapterId\":\"xunzi_ch-12\",\"order\":9,\"canonicalText\":\"故古之人為之不然：其取人有道，其用人有法。取人之道，參之以禮；用人之法，禁之以等。行義動靜，度之以禮；知慮取捨，稽之以成；日月積久，校之以功，故卑不得以臨尊，輕不得以縣重，愚不得以謀知，是以萬舉而不過也。故校之以禮，而觀其能安敬也；與之舉措遷移，而觀其能應變也；與之安燕，而觀其能無流慆也；接之以聲色、權利、忿怒、患險，而觀其能無離守也。彼誠有之者，與誠無之者，若白黑然，可詘邪哉！故伯樂不可欺以馬，而君子不可欺以人，此明王之道也。\",\"sentenceIds\":[\"xunzi_ch-12_p-9_s-1\",\"xunzi_ch-12_p-9_s-2\",\"xunzi_ch-12_p-9_s-3\",\"xunzi_ch-12_p-9_s-4\",\"xunzi_ch-12_p-9_s-5\",\"xunzi_ch-12_p-9_s-6\",\"xunzi_ch-12_p-9_s-7\",\"xunzi_ch-12_p-9_s-8\",\"xunzi_ch-12_p-9_s-9\",\"xunzi_ch-12_p-9_s-10\",\"xunzi_ch-12_p-9_s-11\",\"xunzi_ch-12_p-9_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 9 節）中論述道：所以古的人為的不然：他的取人有道，他的用人有國家典章法度。取人的道，參的以禮正義道義道品德修養規程；用人的國家典章法度，禁的以等。行正義道義動靜，度的以禮正義道義道品德修養規程；知慮取捨，稽的以成；日月積久，校的以功，所以卑不得以臨尊，輕不得以縣重，愚不得以謀知，是以萬舉而且不過啊。所以校的以禮正義道義道品德修養規程，而且觀他的能安敬啊；與的舉措遷移，而且觀他的能應變啊；與的安燕，而且觀他的能無流慆啊；接的以聲色、權利、忿怒、患險，而且觀他的能無離守啊。彼誠有的的人或事物，與誠無的的人或事物，若白黑然，可詘邪哉！所以伯樂不可欺以馬，而且君子不可欺以人，此明王的道啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 9 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故古之人為之不然：其取人有道，其用人有法」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故古之人為之不然：其取人有道，其用人有法。取人之道，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-10\",\"chapterId\":\"xunzi_ch-12\",\"order\":10,\"canonicalText\":\"人主欲得善射射1遠中微者，縣貴爵重賞以招致之。內不可以阿子弟，外不可以隱遠人，能中是者取之；是豈不必得之之道也哉！雖聖人不能易也。欲得善馭及2速致遠者，一日而千里，縣貴爵重賞以招致之。內不可以阿子弟，外不可以隱遠人，能致是者取之；是豈不必得之之道也哉！雖聖人不能易也。欲治國馭民，調壹上下，將內以固城，外以拒難，治則制人，人不能制也；亂則危辱滅亡，可立而待也。然而求卿相輔佐，則獨不若是其公也，案唯便嬖親比己者之用也，豈不過甚矣哉！故有社稷者，莫不欲彊，俄則弱矣；莫不欲安，俄則危矣；莫不欲存，俄則亡矣。古有萬國，今有十數焉，是無它故，莫不失之是也。故明主有私人以金石珠玉，無私人以官職事業，是何也？曰：本不利於所私也。彼不能而主使之，則是主闇也；臣不能而誣能，則是臣詐也。主闇於上，臣詐於下，滅亡無日，俱害之道也。夫文王非無貴戚也，非無子弟也，非無便嬖也，倜然乃舉太公於州人而用之，豈私之也哉！以為親邪？則周姬姓也，而彼姜姓也；以為故邪？則未嘗相識也；以為好麗邪？則夫人行年七十有二，齫然兩3齒墮矣。然而用之者，夫文王欲立貴道，欲白貴名，以惠天下，而不可以獨也。非於是子莫足以舉之，故舉是子而用之。於是乎貴道果立，貴名果白，兼制天下，立七十一國姬姓獨居五十三人。周之子孫，苟非狂惑者，莫不為天下之顯諸侯，如是者能愛人也。故舉天下之大道，立天下之大功，然後隱其所憐所愛，其下猶足以為天下之顯諸侯。故曰：唯明主為能愛其所愛，闇主則必危其所愛。此之謂也。\",\"sentenceIds\":[\"xunzi_ch-12_p-10_s-1\",\"xunzi_ch-12_p-10_s-2\",\"xunzi_ch-12_p-10_s-3\",\"xunzi_ch-12_p-10_s-4\",\"xunzi_ch-12_p-10_s-5\",\"xunzi_ch-12_p-10_s-6\",\"xunzi_ch-12_p-10_s-7\",\"xunzi_ch-12_p-10_s-8\",\"xunzi_ch-12_p-10_s-9\",\"xunzi_ch-12_p-10_s-10\",\"xunzi_ch-12_p-10_s-11\",\"xunzi_ch-12_p-10_s-12\",\"xunzi_ch-12_p-10_s-13\",\"xunzi_ch-12_p-10_s-14\",\"xunzi_ch-12_p-10_s-15\",\"xunzi_ch-12_p-10_s-16\",\"xunzi_ch-12_p-10_s-17\",\"xunzi_ch-12_p-10_s-18\",\"xunzi_ch-12_p-10_s-19\",\"xunzi_ch-12_p-10_s-20\",\"xunzi_ch-12_p-10_s-21\",\"xunzi_ch-12_p-10_s-22\",\"xunzi_ch-12_p-10_s-23\",\"xunzi_ch-12_p-10_s-24\",\"xunzi_ch-12_p-10_s-25\",\"xunzi_ch-12_p-10_s-26\",\"xunzi_ch-12_p-10_s-27\",\"xunzi_ch-12_p-10_s-28\",\"xunzi_ch-12_p-10_s-29\",\"xunzi_ch-12_p-10_s-30\",\"xunzi_ch-12_p-10_s-31\",\"xunzi_ch-12_p-10_s-32\",\"xunzi_ch-12_p-10_s-33\",\"xunzi_ch-12_p-10_s-34\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 10 節）中論述道：人主欲得善射射1遠中微的人或事物，縣貴爵重賞以招致的。內不可以阿子弟，外不可以隱遠人，能中是的人或事物取的；是豈不必得的的道啊哉！雖聖人不能易啊。欲得善馭及2速致遠的人或事物，一日而且千里，縣貴爵重賞以招致的。內不可以阿子弟，外不可以隱遠人，能致是的人或事物取的；是豈不必得的的道啊哉！欲治國馭民，調壹上下，將內以固城，外以拒難，治則制人，人不能制啊；亂則危辱滅亡，可立而且待啊。然而且求卿相輔佐，則獨不若是他的公啊，案唯便嬖親比己的人或事物的用啊，豈不過甚矣哉！所以有社稷的人或事物，莫不欲彊，俄則弱矣；莫不欲安，俄則危矣；莫不欲存，俄則亡矣。古有萬國，今有十數焉，是無它所以，莫不失的是啊。所以明主有私人以金石珠玉，無私人以官職事業，是何啊？說道：：本不利於所私啊。彼不能而且主使的，則是主闇啊；臣不能而且誣能，則是臣詐啊。主闇於上，臣詐於下，滅亡無日，俱害的道啊。夫文王絕不是無貴戚啊，絕不是無子弟啊，絕不是無便嬖啊，倜然乃舉太公於州人而且用的，豈私的啊哉！以為親邪？則周姬姓啊，而且彼姜姓啊；以為所以邪？則未嘗相識啊；以為好麗邪？則夫人行年七十有二，齫然兩3齒墮矣。然而且用的的人或事物，夫文王欲立貴道，欲白貴名，以惠天下，而且不可以獨啊。絕不是於是子莫足以舉的，所以舉是子而且用的。於是乎貴道果立，貴名果白，兼制天下，立七十一國姬姓獨居五十三人。周的子孫，苟絕不是狂惑的人或事物，莫不為天下的顯諸侯，如是的人或事物能愛人啊。所以舉天下的大道，立天下的大功，然後隱他的所憐所愛，他的下猶足以為天下的顯諸侯。所以古聖先賢說道：：唯明主為能愛他的所愛，闇主則必危他的所愛。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 10 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「人主欲得善射射1遠中微者，縣貴爵重賞以招致之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「人主欲得善射射1遠中微者，縣貴爵重賞以招致之。內不可……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-11\",\"chapterId\":\"xunzi_ch-12\",\"order\":11,\"canonicalText\":\"牆之外，目不見也；裏之前，耳不聞也；而人主之守司，遠者天下，近者境內，不可不略知也。天下之變，境內之事，有弛易齵差者矣，而人主無由知之，則是拘脅蔽塞之端也。耳目之明，如是其狹也；人主之守司，如是其廣也；其中不可以不知也，如是其危也。然則人主將何以知之？曰：便嬖左右者，人主之所以窺遠收眾之門戶牖嚮也，不可不早具也。故人主必將有便嬖左右足信者，然後可。其知惠足使規物，其端誠足使定物，然後可；夫是之謂國具。人主不能不有遊觀安燕之時，則不得不有疾病物故之變焉。如是，國者，事物之至也如泉原，一物不應，亂之端也。故曰：人主不可以獨也。卿相輔佐，人主之基杖也，不可不早具也。故人主必將有卿相輔佐足任者，然後可。其德音足以填撫百姓，其知慮足以應待萬變，然後可；夫是之謂國具。四鄰諸侯之相與，不可以不相接也，然而不必相親也，故人主必將有足使喻志決疑於遠方者，然後可。其辯說足以解煩，其知慮足以決疑，其齊斷足以距難，不還秩，不反君，然而應薄扞患，足以持社稷，然後可，夫是之謂國具。故人主無便嬖左右足信者，謂之闇；無卿相輔佐足任使者，謂之獨；所使於四鄰諸侯者非其人，謂之孤；孤獨而晻，謂之危。國雖若存，古之人曰亡矣。《詩》曰：「濟濟多士，文王以寧。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-12_p-11_s-1\",\"xunzi_ch-12_p-11_s-2\",\"xunzi_ch-12_p-11_s-3\",\"xunzi_ch-12_p-11_s-4\",\"xunzi_ch-12_p-11_s-5\",\"xunzi_ch-12_p-11_s-6\",\"xunzi_ch-12_p-11_s-7\",\"xunzi_ch-12_p-11_s-8\",\"xunzi_ch-12_p-11_s-9\",\"xunzi_ch-12_p-11_s-10\",\"xunzi_ch-12_p-11_s-11\",\"xunzi_ch-12_p-11_s-12\",\"xunzi_ch-12_p-11_s-13\",\"xunzi_ch-12_p-11_s-14\",\"xunzi_ch-12_p-11_s-15\",\"xunzi_ch-12_p-11_s-16\",\"xunzi_ch-12_p-11_s-17\",\"xunzi_ch-12_p-11_s-18\",\"xunzi_ch-12_p-11_s-19\",\"xunzi_ch-12_p-11_s-20\",\"xunzi_ch-12_p-11_s-21\",\"xunzi_ch-12_p-11_s-22\",\"xunzi_ch-12_p-11_s-23\",\"xunzi_ch-12_p-11_s-24\",\"xunzi_ch-12_p-11_s-25\",\"xunzi_ch-12_p-11_s-26\",\"xunzi_ch-12_p-11_s-27\",\"xunzi_ch-12_p-11_s-28\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 11 節）中論述道：牆的外，目不見啊；裏的前，耳不聞啊；而且人主的守司，遠的人或事物天下，近的人或事物境內，不可不略知啊。天下的變，境內的事，有弛易齵差的人或事物矣，而且人主無由知的，則是拘脅蔽塞的端啊。耳目的明，如是他的狹啊；人主的守司，如是他的廣啊；他的中不可以不知啊，如是他的危啊。然則人主將何以知的？說道：：便嬖左右的人或事物，人主的所以窺遠收眾的門戶牖嚮啊，不可不早具啊。所以人主必將有便嬖左右足信的人或事物，然後可。他的知惠足使規物，他的端誠足使定物，然後可；這就是儒家所稱的國具。人主不能不有遊觀安燕的時，則不得不有疾病物所以的變焉。如是，國的人或事物，事物的至啊如泉原，一物不應，亂的端啊。所以古聖先賢說道：：人主不可以獨啊。卿相輔佐，人主的基杖啊，不可不早具啊。所以人主必將有卿相輔佐足任的人或事物，然後可。他的品德修養音足以填撫百姓，他的知慮足以應待萬變，然後可；這就是儒家所稱的國具。四鄰諸侯的相與，不可以不相接啊，然而且不必相親啊，所以人主必將有足使喻志決疑於遠方的人或事物，然後可。他的辯說足以解煩，他的知慮足以決疑，他的齊斷足以距難，不還秩，不反君，然而且應薄扞患，足以持社稷，然後可，這就是儒家所稱的國具。所以人主無便嬖左右足信的人或事物，謂的闇；無卿相輔佐足任使的人或事物，謂的獨；所使於四鄰諸侯的人或事物絕不是他的人，謂的孤；孤獨而且晻，謂的危。國雖若存，古的人說道：亡矣。《詩》說道：：濟濟多士，文王以寧。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 11 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「牆之外，目不見也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「牆之外，目不見也；裏之前，耳不聞也；而人主之守司，遠……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-12_p-12\",\"chapterId\":\"xunzi_ch-12\",\"order\":12,\"canonicalText\":\"材人：願愨拘錄，計數纖嗇，而無敢遺喪，是官人使吏之材也。脩飭端正，尊法敬分，而無傾側之心，守職脩業，不敢損益，可傳世也，而不可使侵奪，是士大夫官師之材也。知隆禮義之為尊君也，知好士之為美名也，知愛民之為安國也，知有常法之為一俗也，知尚賢使能之為長功也，知務本禁末之為多材也，知無與下爭小利之為便於事也，知明制度，權物稱用之為不泥也，是卿相輔佐之材也，未及君道也。能論官此三材者而無失其次，是謂人主之道也。若是則身佚而國治，功大而名美，上可以王，下可以霸，是人主之要守也。人主不能論此三材者，不知道此道，安值將卑埶出勞，併耳目之樂，而親自貫日而治詳，一日而曲辨之，慮與臣下爭小察而綦偏能，自古及今，未有如此而不亂者也。是所謂視乎不可見，聽乎不可聞，為乎不可成，此之謂也。\",\"sentenceIds\":[\"xunzi_ch-12_p-12_s-1\",\"xunzi_ch-12_p-12_s-2\",\"xunzi_ch-12_p-12_s-3\",\"xunzi_ch-12_p-12_s-4\",\"xunzi_ch-12_p-12_s-5\",\"xunzi_ch-12_p-12_s-6\",\"xunzi_ch-12_p-12_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・君道》（第 12 節）中論述道：材人：願愨拘錄，計數纖嗇，而且無敢遺喪，是官人使吏的材啊。脩飭端正，尊國家典章法度敬分，而且無傾側的心，守職脩業，不敢損益，可傳世啊，而且不可使侵奪，是士大夫官師的材啊。知隆禮正義道義道品德修養規程正義道義的為尊君啊，知好士的為美名啊，知愛民的為安國啊，知有常國家典章法度的為一俗啊，知尚賢使能的為長功啊，知務本禁末的為多材啊，知無與下爭小利的為便於事啊，知明制度，權物稱用的為不泥啊，是卿相輔佐的材啊，未及君道啊。能論官此三材的人或事物而且無失他的次，是謂人主的道啊。若是則身佚而且國治，功大而且名美，上可以王，下可以霸，是人主的要守啊。人主不能論此三材的人或事物，不知道此道，安值將卑埶出勞，併耳目的樂，而且親自貫日而且治詳，一日而且曲辨的，慮與臣下爭小察而且綦偏能，自古及今，未有如此而且不亂的人或事物啊。是所謂視乎不可見，聽乎不可聞，為乎不可成，此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈君道〉（第 12 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「材人：願愨拘錄，計數纖嗇，而無敢遺喪，是官人使吏之材也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「材人：願愨拘錄，計數纖嗇，而無敢遺喪，是官人使吏之材……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"xunzi_ch-12_p-1_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":1,\"canonicalText\":\"有亂君，無亂國；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":2,\"canonicalText\":\"有治人，無治法，羿之法非亡也，而羿不世中；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":3,\"canonicalText\":\"禹之法猶存，而夏不世王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":4,\"canonicalText\":\"故法不能獨立，類不能自行；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":5,\"canonicalText\":\"得其人則存，失其人則亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":6,\"canonicalText\":\"法者、治之端也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":7,\"canonicalText\":\"君子者、法之原也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":8,\"canonicalText\":\"故有君子，則法雖省，足以遍矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":9,\"canonicalText\":\"無君子，則法雖具，失先後之施，不能應事之變，足以亂矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":10,\"canonicalText\":\"不知法之義，而正法之數者，雖博臨事必亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":11,\"canonicalText\":\"故明主急得其人，而闇主急得其埶。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":12,\"canonicalText\":\"急得其人，則身佚而國治，功大而名美，上可以王，下可以霸；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":13,\"canonicalText\":\"不急得其人，而急得其埶，則身勞而國亂，功廢而名辱，社稷必危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":14,\"canonicalText\":\"故君人者，勞於索之，而休於使之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":15,\"canonicalText\":\"《書》曰：「惟文王敬忌，一人以擇。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-1_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-1\",\"order\":16,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":1,\"canonicalText\":\"合符節，別契券者，所以為信也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":2,\"canonicalText\":\"上好權謀，則臣下百吏誕詐之人乘是而後欺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":3,\"canonicalText\":\"探籌、投鉤者，所以為公也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":4,\"canonicalText\":\"上好曲私，則臣下百吏乘是而後偏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":5,\"canonicalText\":\"衡石稱縣者，所以為平也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":6,\"canonicalText\":\"上好覆傾，則臣下百吏乘是而後險。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":7,\"canonicalText\":\"鬥斛敦概者，所以為嘖也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":8,\"canonicalText\":\"上好貪利，則臣下百吏乘是而後豐取刻與，以無度取於民。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":9,\"canonicalText\":\"故械數者，治之流也，非治之原也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":10,\"canonicalText\":\"君子者，治之原也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":11,\"canonicalText\":\"官人守數，君子養原；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":12,\"canonicalText\":\"原清則流清，原濁則流濁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":13,\"canonicalText\":\"故上好禮義，尚賢使能，無貪利之心，則下亦將綦辭讓，致忠信，而謹於臣子矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":14,\"canonicalText\":\"如是則雖在小民，不待合符節，別契券而信，不待探籌投鉤而公，不待衝石稱縣而平，不待鬥斛敦概而嘖。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":15,\"canonicalText\":\"故賞不用而民勸，罰不用而民服，有司不勞而事治，政令不煩而俗美。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":16,\"canonicalText\":\"百姓莫敢不順上之法，象上之志，而勸上之事，而安樂之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":17,\"canonicalText\":\"故藉歛忘費，事業忘勞，寇難忘死，城郭不待飾而固，兵刃不待陵而勁，敵國不待服而詘，四海之民不待令而一，夫是之謂至平。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":18,\"canonicalText\":\"《詩》曰：「王猶允塞，徐方既來。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-2_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-2\",\"order\":19,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":1,\"canonicalText\":\"請問為人君？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":2,\"canonicalText\":\"曰：以禮分施，均遍而不偏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":3,\"canonicalText\":\"請問為人臣？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":4,\"canonicalText\":\"曰：以禮侍君，忠順而不懈。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":5,\"canonicalText\":\"請問為人父？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":6,\"canonicalText\":\"曰：寬惠而有禮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":7,\"canonicalText\":\"請問為人子？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":8,\"canonicalText\":\"曰：敬愛而致文。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":9,\"canonicalText\":\"請問為人兄？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":10,\"canonicalText\":\"曰：慈愛而見友。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":11,\"canonicalText\":\"請問為人弟？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":12,\"canonicalText\":\"曰：敬詘而不苟。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":13,\"canonicalText\":\"請問為人夫？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":14,\"canonicalText\":\"曰：致功而不流，致臨而有辨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":15,\"canonicalText\":\"請問為人妻？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":16,\"canonicalText\":\"曰：夫有禮則柔從聽侍，夫無禮則恐懼而自竦也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":17,\"canonicalText\":\"此道也，偏立而亂，俱立而治，其足以稽矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":18,\"canonicalText\":\"請問兼能之奈何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":19,\"canonicalText\":\"曰：審之禮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":20,\"canonicalText\":\"古者先王審禮以方皇周浹於天下，動無不當也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":21,\"canonicalText\":\"故君子恭而不難，敬而不鞏，貧窮而不約，富貴而不驕，並遇變態而不窮，審之禮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":22,\"canonicalText\":\"故君子之於禮，敬而安之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":23,\"canonicalText\":\"其於事也，徑而不失；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":24,\"canonicalText\":\"其於人也，寡怨寬裕而無阿；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":25,\"canonicalText\":\"其為身也，謹修飾而不危；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-26\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":26,\"canonicalText\":\"其應變故也，齊給便捷而不惑；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-27\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":27,\"canonicalText\":\"其於天地萬物也，不務說其所以然，而致善用其材；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-28\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":28,\"canonicalText\":\"其於百官之事伎藝之人也，不與之爭能，而致善用其功；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-29\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":29,\"canonicalText\":\"其待上也，忠順而不懈；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-30\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":30,\"canonicalText\":\"其使下也，均遍而不偏；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-31\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":31,\"canonicalText\":\"其交遊也，緣類而有義；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-32\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":32,\"canonicalText\":\"其居鄉里也，容而不亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-33\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":33,\"canonicalText\":\"是故窮則必有名，達則必有功，仁厚兼覆天下而不閔，明達用天地理萬變而不疑，血氣和平，志意廣大，行義塞於天地之間，仁智之極也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-34\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":34,\"canonicalText\":\"夫是之謂聖人；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-3_s-35\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-3\",\"order\":35,\"canonicalText\":\"審之禮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-4_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-4\",\"order\":1,\"canonicalText\":\"請問為國？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-4_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-4\",\"order\":2,\"canonicalText\":\"曰聞修身，未嘗聞為國也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-4_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-4\",\"order\":3,\"canonicalText\":\"君者儀也，民者景也，儀正而景正。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-4_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-4\",\"order\":4,\"canonicalText\":\"君者槃也，民者水也，槃圓而水圓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-4_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-4\",\"order\":5,\"canonicalText\":\"君者盂也，盂方而水方。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-4_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-4\",\"order\":6,\"canonicalText\":\"君射則臣決。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-4_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-4\",\"order\":7,\"canonicalText\":\"楚莊王好細腰，故朝有餓人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-4_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-4\",\"order\":8,\"canonicalText\":\"故曰：聞修身，未嘗聞為國也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":1,\"canonicalText\":\"君者，民之原也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":2,\"canonicalText\":\"原清則流清，原濁則流濁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":3,\"canonicalText\":\"故有社稷者而不能愛民，不能利民，而求民之親愛己，不可得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":4,\"canonicalText\":\"民不親不愛，而求為己用，為己死，不可得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":5,\"canonicalText\":\"民不為己用，不為己死，而求兵之勁，城之固，不可得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":6,\"canonicalText\":\"兵不勁，城不固，而求敵之不至，不可得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":7,\"canonicalText\":\"敵至而求無危削，不滅亡，不可得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":8,\"canonicalText\":\"危削滅亡之情，舉積此矣，而求安樂，是狂生者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":9,\"canonicalText\":\"狂生者，不胥時而落。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":10,\"canonicalText\":\"故人主欲彊固安樂，則莫若反之民；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":11,\"canonicalText\":\"欲附下一民，則莫若反之政；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":12,\"canonicalText\":\"欲脩政美俗，則莫若求其人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":13,\"canonicalText\":\"彼或蓄積而得之者不世絕。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":14,\"canonicalText\":\"彼其人者，生乎今之世，而志乎古之道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":15,\"canonicalText\":\"以天下之王公莫好之也，然而是子獨好之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":16,\"canonicalText\":\"以天下之民莫為1之也，然而是子獨為之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":17,\"canonicalText\":\"好之者貧，為之者窮，然而是子猶將為之也，不為少頃輟焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":18,\"canonicalText\":\"曉然獨明於先王之所以得之，所以失之，知國之安危臧否，若別白黑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":19,\"canonicalText\":\"是其人也，大用之，則天下為一，諸侯為臣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":20,\"canonicalText\":\"小用之，則威行鄰敵；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":21,\"canonicalText\":\"縱不能用，使無去其疆域，則國終身無故。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":22,\"canonicalText\":\"故君人者，愛民而安，好士而榮，兩者無一焉而亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":23,\"canonicalText\":\"《詩》曰：「介人維藩，大師為垣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-5_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-5\",\"order\":24,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":1,\"canonicalText\":\"道者，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":2,\"canonicalText\":\"曰：君之所1道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":3,\"canonicalText\":\"君者，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":4,\"canonicalText\":\"曰：能羣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":5,\"canonicalText\":\"能羣也者，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":6,\"canonicalText\":\"曰：善生養人者也，善班治人者也，善顯設人者也，善藩飾人者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":7,\"canonicalText\":\"善生養人者人親之，善班治人者人安之，善顯設人者人樂之，善藩飾人者人榮之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":8,\"canonicalText\":\"四統者俱，而天下歸之，夫是之謂能羣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":9,\"canonicalText\":\"不能生養人者，人不親也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":10,\"canonicalText\":\"不能班治人者，人不安也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":11,\"canonicalText\":\"不能顯設人者，人不樂也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":12,\"canonicalText\":\"不能藩飾人者，人不榮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":13,\"canonicalText\":\"四統者亡，而天下去之，夫是之謂匹夫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":14,\"canonicalText\":\"故曰：道存則國存，道亡則國亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":15,\"canonicalText\":\"省工賈，眾農夫，禁盜賊，除姦邪：是所以生養之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":16,\"canonicalText\":\"天子三公，諸侯一相，大夫擅官，士保職，莫不法度而公：是所以班治之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":17,\"canonicalText\":\"論德而定次，量能而授官，皆使人載其事，而各得其所宜，上賢使之為三公，次賢使之為諸侯，下賢使之為士大夫：是所以顯設之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":18,\"canonicalText\":\"修冠弁衣裳，黼黻文章，琱琢刻鏤，皆有等差：是所以藩飾之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":19,\"canonicalText\":\"故由天子至於庶人也，莫不騁其能，得其志，安樂其事，是所同也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":20,\"canonicalText\":\"衣煖而食充，居安而遊樂，事時制明而用足，是又所同也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":21,\"canonicalText\":\"若夫重色而成文章，重味而成珍備，是所衍也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":22,\"canonicalText\":\"聖王財衍，以明辨異，上以飾賢良而明貴賤，下以飾長幼而明親疏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":23,\"canonicalText\":\"上在王公之朝，下在百姓之家，天下曉然皆知其所非以為異也，將以明分達治而保萬世也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":24,\"canonicalText\":\"故天子諸侯無靡費之用，士大夫無流淫之行，百吏官人無怠慢之事，眾庶百姓無姦怪之俗，無盜賊之罪，其能以稱義徧矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":25,\"canonicalText\":\"故曰：治則衍及百姓，亂則不足及王公。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-6_s-26\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-6\",\"order\":26,\"canonicalText\":\"此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-7_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-7\",\"order\":1,\"canonicalText\":\"至道大形：隆禮至法則國有常，尚賢使能則民知方，纂論公察則民不疑，賞克罰偷則民不怠，兼聽齊明則天下歸之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-7_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-7\",\"order\":2,\"canonicalText\":\"然後明分職，序事業，材技官能，莫不治理，則公道達而私門塞矣，公義明而私事息矣：如是，則德厚者進而佞說者止，貪利者退而廉節者起。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-7_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-7\",\"order\":3,\"canonicalText\":\"《書》曰：「先時者殺無赦，不逮時者殺無赦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-7_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-7\",\"order\":4,\"canonicalText\":\"」人習其事而固，人之百事，如耳目鼻口之不可以相借官也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-7_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-7\",\"order\":5,\"canonicalText\":\"故職分而民不慢1，次定而序不亂，兼聽齊明而百姓不留：如是，則臣下百吏至於庶人，莫不修己而後敢安止，誠能而後敢受職；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-7_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-7\",\"order\":6,\"canonicalText\":\"百姓易俗，小人變心，姦怪之屬莫不反愨：夫是之謂政教之極。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-7_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-7\",\"order\":7,\"canonicalText\":\"故天子不視而見，不聽而聰，不慮而知，不動而功，塊然獨坐而天下從之如一體，如四胑之從心：夫是之謂大形。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-7_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-7\",\"order\":8,\"canonicalText\":\"《詩》曰：「溫溫恭人，維德之基。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-7_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-7\",\"order\":9,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":1,\"canonicalText\":\"為人主者，莫不欲彊而惡弱，欲安而惡危，欲榮而惡辱，是禹桀之所同也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":2,\"canonicalText\":\"要此三欲，闢此三惡，果何道而便？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":3,\"canonicalText\":\"曰：在慎取相，道莫徑是矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":4,\"canonicalText\":\"故知而不仁，不可；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":5,\"canonicalText\":\"仁而不知，不可；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":6,\"canonicalText\":\"既知且仁，是人主之寶也，王霸之佐也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":7,\"canonicalText\":\"不急得，不知；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":8,\"canonicalText\":\"得而不用，不仁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":9,\"canonicalText\":\"無其人而幸有其功，愚莫大焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":10,\"canonicalText\":\"今人主有大患：使賢者為之，則與不肖者規之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":11,\"canonicalText\":\"使知者慮之，則與愚者論之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":12,\"canonicalText\":\"使脩士行之，則與汙邪之人疑之，雖欲成功，得乎哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":13,\"canonicalText\":\"譬之，是猶立直木而恐其景之枉也，惑莫大焉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":14,\"canonicalText\":\"語曰：好女之色，惡者之孽也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":15,\"canonicalText\":\"公正之士，眾人之痤也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":16,\"canonicalText\":\"脩道之人，汙邪之賊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":17,\"canonicalText\":\"今使汙邪之人，論其怨賊，而求其無偏，得乎哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-8_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-8\",\"order\":18,\"canonicalText\":\"譬之，是猶立枉木而求其景之直也，亂莫大焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":1,\"canonicalText\":\"故古之人為之不然：其取人有道，其用人有法。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":2,\"canonicalText\":\"取人之道，參之以禮；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":3,\"canonicalText\":\"用人之法，禁之以等。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":4,\"canonicalText\":\"行義動靜，度之以禮；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":5,\"canonicalText\":\"知慮取捨，稽之以成；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":6,\"canonicalText\":\"日月積久，校之以功，故卑不得以臨尊，輕不得以縣重，愚不得以謀知，是以萬舉而不過也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":7,\"canonicalText\":\"故校之以禮，而觀其能安敬也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":8,\"canonicalText\":\"與之舉措遷移，而觀其能應變也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":9,\"canonicalText\":\"與之安燕，而觀其能無流慆也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":10,\"canonicalText\":\"接之以聲色、權利、忿怒、患險，而觀其能無離守也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":11,\"canonicalText\":\"彼誠有之者，與誠無之者，若白黑然，可詘邪哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-9_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-9\",\"order\":12,\"canonicalText\":\"故伯樂不可欺以馬，而君子不可欺以人，此明王之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":1,\"canonicalText\":\"人主欲得善射射1遠中微者，縣貴爵重賞以招致之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":2,\"canonicalText\":\"內不可以阿子弟，外不可以隱遠人，能中是者取之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":3,\"canonicalText\":\"是豈不必得之之道也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":4,\"canonicalText\":\"雖聖人不能易也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":5,\"canonicalText\":\"欲得善馭及2速致遠者，一日而千里，縣貴爵重賞以招致之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":6,\"canonicalText\":\"內不可以阿子弟，外不可以隱遠人，能致是者取之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":7,\"canonicalText\":\"是豈不必得之之道也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":8,\"canonicalText\":\"雖聖人不能易也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":9,\"canonicalText\":\"欲治國馭民，調壹上下，將內以固城，外以拒難，治則制人，人不能制也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":10,\"canonicalText\":\"亂則危辱滅亡，可立而待也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":11,\"canonicalText\":\"然而求卿相輔佐，則獨不若是其公也，案唯便嬖親比己者之用也，豈不過甚矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":12,\"canonicalText\":\"故有社稷者，莫不欲彊，俄則弱矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":13,\"canonicalText\":\"莫不欲安，俄則危矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":14,\"canonicalText\":\"莫不欲存，俄則亡矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":15,\"canonicalText\":\"古有萬國，今有十數焉，是無它故，莫不失之是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":16,\"canonicalText\":\"故明主有私人以金石珠玉，無私人以官職事業，是何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":17,\"canonicalText\":\"曰：本不利於所私也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":18,\"canonicalText\":\"彼不能而主使之，則是主闇也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":19,\"canonicalText\":\"臣不能而誣能，則是臣詐也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":20,\"canonicalText\":\"主闇於上，臣詐於下，滅亡無日，俱害之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":21,\"canonicalText\":\"夫文王非無貴戚也，非無子弟也，非無便嬖也，倜然乃舉太公於州人而用之，豈私之也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":22,\"canonicalText\":\"以為親邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":23,\"canonicalText\":\"則周姬姓也，而彼姜姓也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":24,\"canonicalText\":\"以為故邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":25,\"canonicalText\":\"則未嘗相識也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-26\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":26,\"canonicalText\":\"以為好麗邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-27\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":27,\"canonicalText\":\"則夫人行年七十有二，齫然兩3齒墮矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-28\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":28,\"canonicalText\":\"然而用之者，夫文王欲立貴道，欲白貴名，以惠天下，而不可以獨也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-29\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":29,\"canonicalText\":\"非於是子莫足以舉之，故舉是子而用之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-30\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":30,\"canonicalText\":\"於是乎貴道果立，貴名果白，兼制天下，立七十一國姬姓獨居五十三人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-31\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":31,\"canonicalText\":\"周之子孫，苟非狂惑者，莫不為天下之顯諸侯，如是者能愛人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-32\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":32,\"canonicalText\":\"故舉天下之大道，立天下之大功，然後隱其所憐所愛，其下猶足以為天下之顯諸侯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-33\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":33,\"canonicalText\":\"故曰：唯明主為能愛其所愛，闇主則必危其所愛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-10_s-34\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-10\",\"order\":34,\"canonicalText\":\"此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":1,\"canonicalText\":\"牆之外，目不見也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":2,\"canonicalText\":\"裏之前，耳不聞也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":3,\"canonicalText\":\"而人主之守司，遠者天下，近者境內，不可不略知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":4,\"canonicalText\":\"天下之變，境內之事，有弛易齵差者矣，而人主無由知之，則是拘脅蔽塞之端也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":5,\"canonicalText\":\"耳目之明，如是其狹也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":6,\"canonicalText\":\"人主之守司，如是其廣也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":7,\"canonicalText\":\"其中不可以不知也，如是其危也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":8,\"canonicalText\":\"然則人主將何以知之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":9,\"canonicalText\":\"曰：便嬖左右者，人主之所以窺遠收眾之門戶牖嚮也，不可不早具也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":10,\"canonicalText\":\"故人主必將有便嬖左右足信者，然後可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":11,\"canonicalText\":\"其知惠足使規物，其端誠足使定物，然後可；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":12,\"canonicalText\":\"夫是之謂國具。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":13,\"canonicalText\":\"人主不能不有遊觀安燕之時，則不得不有疾病物故之變焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":14,\"canonicalText\":\"如是，國者，事物之至也如泉原，一物不應，亂之端也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":15,\"canonicalText\":\"故曰：人主不可以獨也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":16,\"canonicalText\":\"卿相輔佐，人主之基杖也，不可不早具也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":17,\"canonicalText\":\"故人主必將有卿相輔佐足任者，然後可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":18,\"canonicalText\":\"其德音足以填撫百姓，其知慮足以應待萬變，然後可；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":19,\"canonicalText\":\"夫是之謂國具。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":20,\"canonicalText\":\"四鄰諸侯之相與，不可以不相接也，然而不必相親也，故人主必將有足使喻志決疑於遠方者，然後可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":21,\"canonicalText\":\"其辯說足以解煩，其知慮足以決疑，其齊斷足以距難，不還秩，不反君，然而應薄扞患，足以持社稷，然後可，夫是之謂國具。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":22,\"canonicalText\":\"故人主無便嬖左右足信者，謂之闇；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":23,\"canonicalText\":\"無卿相輔佐足任使者，謂之獨；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":24,\"canonicalText\":\"所使於四鄰諸侯者非其人，謂之孤；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":25,\"canonicalText\":\"孤獨而晻，謂之危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-26\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":26,\"canonicalText\":\"國雖若存，古之人曰亡矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-27\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":27,\"canonicalText\":\"《詩》曰：「濟濟多士，文王以寧。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-11_s-28\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-11\",\"order\":28,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-12_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-12\",\"order\":1,\"canonicalText\":\"材人：願愨拘錄，計數纖嗇，而無敢遺喪，是官人使吏之材也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-12_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-12\",\"order\":2,\"canonicalText\":\"脩飭端正，尊法敬分，而無傾側之心，守職脩業，不敢損益，可傳世也，而不可使侵奪，是士大夫官師之材也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-12_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-12\",\"order\":3,\"canonicalText\":\"知隆禮義之為尊君也，知好士之為美名也，知愛民之為安國也，知有常法之為一俗也，知尚賢使能之為長功也，知務本禁末之為多材也，知無與下爭小利之為便於事也，知明制度，權物稱用之為不泥也，是卿相輔佐之材也，未及君道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-12_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-12\",\"order\":4,\"canonicalText\":\"能論官此三材者而無失其次，是謂人主之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-12_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-12\",\"order\":5,\"canonicalText\":\"若是則身佚而國治，功大而名美，上可以王，下可以霸，是人主之要守也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-12_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-12\",\"order\":6,\"canonicalText\":\"人主不能論此三材者，不知道此道，安值將卑埶出勞，併耳目之樂，而親自貫日而治詳，一日而曲辨之，慮與臣下爭小察而綦偏能，自古及今，未有如此而不亂者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-12_p-12_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-12\",\"passageId\":\"xunzi_ch-12_p-12\",\"order\":7,\"canonicalText\":\"是所謂視乎不可見，聽乎不可聞，為乎不可成，此之謂也。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
